def _replace_surrogates(error: UnicodeError) -> tuple[bytes, int]:
    """Encodes surrogates as .NET encodes the same UTF-16 string, so all runtimes write the same bytes (SER-005): a high
    surrogate followed by a low one as the character they encode together, and any other surrogate as U+FFFD. The
    encoder reports a run of surrogates as one error. It only accepts ASCII replacement text, so the replacement is
    given as bytes."""
    assert isinstance(error, UnicodeEncodeError)
    text, i, end = error.object, error.start, error.end
    encoded = bytearray()
    while i < end:
        high = ord(text[i])
        low = ord(text[i + 1]) if i + 1 < end else 0
        if 0xD800 <= high < 0xDC00 and 0xDC00 <= low < 0xE000:
            encoded += chr(0x10000 + ((high - 0xD800) << 10) + (low - 0xDC00)).encode("utf-8")
            i += 2
        else:
            encoded += b"\xef\xbf\xbd"
            i += 1
    return bytes(encoded), end


